(* [comment removed for export] *)
Record SENV (tp : word) (TSD CTX TH : Z) (m : mem) : Prop := mkSENV {
  se_tsdi : rw_cells asegs m 1821152 [C1 (b8 1); CB 3 [b8 0; b8 0; b8 0]; C4 (wz 0)];         (* [comment removed for export] *)
  se_tp   : rw_cells asegs m (bv_unsigned tp + -88) [C8 (wz TSD)];
  se_tsd  : rw_cells asegs m TSD [C8 (wz CTX)];
  se_ctx  : rw_cells asegs m (CTX + 152) [C8 (wz TH)];
  se_can  : rw_cells asegs m 1821148 [C1 (b8 1)];                                                (* [comment removed for export] *)
  se_got  : rw_cells asegs m 1778520 (map (fun v => C8 (wz v)) AGOT_VALS);                        (* [comment removed for export] *)
  se_shb  : rw_cells asegs m 1823096 [C8 (wz 2147450880)];                                       (* [comment removed for export] *)
  se_hme  : rw_cells asegs m 1826400 [C8 (wz 140737488355327); C8 (wz 0); C8 (wz 0)];            (* [comment removed for export] *)
  se_thresh : rw_cells asegs m 2420000 [C8 (wz 0xffffffffffffffff)];                                        (* [comment removed for export] *)
  se_mlim : rw_cells asegs m 2420024 [C8 (wz 0)];                                                (* [comment removed for export] *)
  se_dpm  : rw_cells asegs m 2420140 [C1 (b8 0)];                                                (* [comment removed for export] *)
  se_rms  : rw_cells asegs m 1786752 [C8 (wz 1714080)];                                          (* [comment removed for export] *)
  se_psc  : rw_cells asegs m 2411552 [C8 (wz 4096)];                                             (* [comment removed for export] *)
  se_name : rw_cells asegs m 1786808 [C8 (wz 0x1bcf6)]                                            (* [comment removed for export] *)
}.

End HCW.


Ltac open_senv E :=
  destruct E as [Etsdi Etp Etsd Ectx Ecan Egot Eshb Ehme Ethresh Emlim Edpm Erms Epsc Ename];
  unfold AGOT_VALS in Egot; cbn [map] in Egot.

